import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;

public class AssetSearchServlet extends HttpServlet {

    private static final Pattern SANITIZE_PATTERN = Pattern.compile("[;'\"\\]");
    private Connection dbConnection;

    @Override
    public void init() throws ServletException {
        try {
            String dbUrl = System.getenv("JDBC_URL");
            String dbUser = System.getenv("DB_USER");
            String dbPass = System.getenv("DB_PASS");
            Class.forName("org.postgresql.Driver");
            dbConnection = DriverManager.getConnection(dbUrl, dbUser, dbPass);
        } catch (Exception e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String assetType = req.getParameter("type");
        String sortField = req.getParameter("sort");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing type parameter");
            return;
        }

        if (tenantId == null || tenantId.isEmpty()) {
            resp.sendError(403, "Missing tenant context");
            return;
        }

        // Validate sort field against allowlist
        String validatedSort = validateSortField(sortField);

        // Build query - type parameter is used in WHERE clause
        String query = buildSearchQuery(assetType, validatedSort, tenantId);

        try {
            Statement stmt = dbConnection.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\": \"").append(rs.getString("id"))
                    .append("\", \"name\": \"").append(rs.getString("name"))
                    .append("\", \"type\": \"").append(rs.getString("asset_type"))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }

    private String validateSortField(String field) {
        if (field == null) return "name";
        switch (field.toLowerCase()) {
            case "name": return "name";
            case "created": return "created_at";
            case "type": return "asset_type";
            default: return "name";
        }
    }

    private String buildSearchQuery(String assetType, String sortField, String tenantId) {
        // Apply regex sanitization to remove dangerous characters
        String cleanType = SANITIZE_PATTERN.matcher(assetType).replaceAll("");
        String cleanTenant = SANITIZE_PATTERN.matcher(tenantId).replaceAll("");

        return "SELECT id, name, asset_type FROM assets WHERE "
            + "tenant_id = '" + cleanTenant + "' "
            + "AND asset_type LIKE '%" + cleanType + "%' "
            + "ORDER BY " + sortField;
    }
}
